select id, poi_id, type, image_path, year, description, upload_user_id, review_status, reject_reason,
       review_time, reviewer_id, create_time, update_time
from media
where upload_user_id = #{uploadUserId}

    and type = #{type}


    and review_status = #{reviewStatus}

order by create_time desc, id desc

select id, poi_id, type, image_path, year, description, upload_user_id, review_status, reject_reason,
       review_time, reviewer_id, create_time, update_time
from media
where poi_id = #{poiId}
  and review_status = #{reviewStatus}

  and type = #{type}

order by abs(year - #{year}) , year desc, id desc
limit 1

SELECT m.id, m.poi_id AS poiId, p.name AS poiName, m.year, m.description, m.review_status AS reviewStatus, m.reject_reason AS rejectReason, m.create_time AS createTime, m.update_time AS updateTime, m.image_path AS imagePath FROM media m INNER JOIN poi p ON m.poi_id = p.id WHERE m.upload_user_id = #{userId} AND m.type = 'memo'
AND m.poi_id = #{poiId}
AND m.year >= #{yearFrom}
AND m.year <= #{yearTo}
ORDER BY m.create_time DESC

